const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const pattern = /^(\d+\.\d+\.\d+)-fpm-alpine$/;
const versions = new Set();
let url = 'https://hub.docker.com/v2/repositories/library/php/tags?page_size=100&ordering=last_updated&name=fpm-alpine';

outer: while (url) {
  const data = await this.helpers.httpRequest({ url, json: true });
  for (const tag of data.results || []) {
    if (new Date(tag.last_updated).getTime() < cutoff) break outer;
    const m = pattern.exec(tag.name);
    if (m) versions.add(m[1]);
  }
  url = data.next;
}

const cmp = (a, b) => {
  const x = a.split('.').map(Number), y = b.split('.').map(Number);
  return x[0] - y[0] || x[1] - y[1] || x[2] - y[2];
};

return [...versions].sort(cmp).map(v => ({ json: { version: v, branch: `php-${v}` } }));
